// ══════════════════════════════════════════════════════════════
//  EXTRACT VALIDATION CONTEXT
//  Reçoit le payload Jenkins (event: pr_validation) via WF1 ou test manuel
//  Multi-projets : owner/repo/projectKey déduits du payload, pas codés en dur
// ══════════════════════════════════════════════════════════════

// ── CONFIG INFRA (secrets & URLs partagés — statiques par nature) ──
const infra = {
  backendUrl:  'http://172.31.172.61:3001',
  sonarUrl:    'http://sonarqube:9000',
  sonarToken:  '__SONARQUBE_TOKEN__',
  githubToken: '__GITHUB_TOKEN__',  // Remplacer par votre token GitHub
};

// ── Déballage du payload (gère toutes les enveloppes possibles) ──
let payload = $input.first().json;

if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = {}; }
}
if (payload && payload.payload) payload = payload.payload;
if (payload && payload.body)    payload = payload.body;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = {}; }
}
if (!payload || typeof payload !== 'object') payload = {};

// ── Extraction PR ──
const pr = payload.pull_request || {};

// ── DYNAMIQUE : déduire owner + repo depuis l'URL de la PR ──
// Ex: https://github.com/souhaiel11/pfe-app-test/pull/18
let repoOwner = '';
let repoName  = '';
if (pr.url) {
  const m = pr.url.match(/github\.com\/([^\/]+)\/([^\/]+)\/pull\//);
  if (m) {
    repoOwner = m[1];
    repoName  = m[2];
  }
}

// ── DYNAMIQUE : project key Sonar depuis le payload ──
const sonarProjectKey = (payload.sonar && payload.sonar.project_key)
  || repoName
  || '';

// ── Config finale (infra statique + projet dynamique) ──
const config = {
  ...infra,
  repoOwner,
  repoName,
  sonarProjectKey,
};

const ctx = {
  config,

  job:         payload.job || '',
  buildNumber: payload.build_number || '',
  buildUrl:    payload.build_url || '',
  buildStatus: payload.status || 'UNKNOWN',

  prNumber: pr.number || null,
  prBranch: pr.branch || '',
  prTarget: pr.target || 'main',
  prUrl:    pr.url || '',
  prTitle:  pr.title || '',

  reports: payload.reports || {},
};

// ── Garde-fous ──
if (!ctx.prNumber) {
  throw new Error('WF3: payload sans pull_request.number — event pr_validation attendu');
}
if (!config.repoOwner || !config.repoName) {
  throw new Error('WF3: impossible de déduire owner/repo depuis pull_request.url = ' + (pr.url || 'vide'));
}

return [{ json: ctx }];

// ══════════════════════════════════════════════════════════════
//  CONSOLIDATE VALIDATION RESULT
//  Sources : build Jenkins (payload) + SonarQube QG (PR) + incidents backend
// ══════════════════════════════════════════════════════════════

const ctx = $('Extract Validation Context').first().json;
const config = ctx.config;

// ── 1. Jenkins : le statut du build PR est DANS le payload ──
const buildStatus = ctx.buildStatus;
const jenkinsPassed = (buildStatus === 'SUCCESS' || buildStatus === 'UNSTABLE');
const jenkinsWarning = (buildStatus === 'UNSTABLE');

// ── 2. SonarQube Quality Gate (PR) — tolère l'absence (Community Edition) ──
let sonarStatus = 'SKIPPED';
let sonarPassed = true;   // non bloquant si indisponible
let sonarDetail = 'PR analysis unavailable (SonarQube Community) — non-blocking';

try {
  const s = $('Get SonarQube PR Quality Gate').first().json;
  const qg = s.projectStatus && s.projectStatus.status;
  if (qg === 'OK') {
    sonarStatus = 'OK'; sonarPassed = true;
    sonarDetail = 'Quality Gate PASSED on PR';
  } else if (qg === 'ERROR' || qg === 'WARN') {
    sonarStatus = qg; sonarPassed = (qg !== 'ERROR');
    const conds = (s.projectStatus.conditions || [])
      .filter(c => c.status === 'ERROR')
      .map(c => `${c.metricKey}: ${c.actualValue} (seuil ${c.errorThreshold})`)
      .slice(0, 5);
    sonarDetail = qg === 'ERROR'
      ? 'Quality Gate FAILED: ' + (conds.join(' | ') || 'conditions non satisfaites')
      : 'Quality Gate WARN';
  }
} catch (e) { /* nœud en erreur → SKIPPED, non bloquant */ }

// ── 3. Retrouver l'incident lié à cette PR (requête SQL directe) ──
let incidentId = null;
try {
  const row = $('Get Incident From DB').first().json;
  if (row && row.id) incidentId = row.id;
} catch (e) { /* aucun incident trouvé → incidentId reste null */ }

// ── 4. Verdict global ──
const validationPassed = jenkinsPassed && sonarPassed;

// ── 5. Commentaire GitHub (markdown) ──
const icon = validationPassed ? '✅' : '❌';
const lines = [
  `## ${icon} Validation automatique du patch IA — ${validationPassed ? 'RÉUSSIE' : 'ÉCHOUÉE'}`,
  '',
  `| Contrôle | Résultat |`,
  `|---|---|`,
  `| Build Jenkins (PR) | ${buildStatus}${jenkinsWarning ? ' ⚠️ (stages en warning)' : ''} — [logs](${ctx.buildUrl}) |`,
  `| SonarQube Quality Gate | ${sonarStatus} — ${sonarDetail} |`,
  '',
  validationPassed
    ? '**Le correctif a passé la validation automatique.** Il est prêt pour la revue humaine avant merge.'
    : '**Le correctif a échoué à la validation automatique.** Ne pas merger en l\'état — consulter les logs du build.',
  '',
  `_WF3 · Post-PR Validation · Build #${ctx.buildNumber} · ${new Date().toISOString()}_`
];

return [{
  json: {
    validationPassed,
    jenkinsPassed,
    jenkinsWarning,
    buildStatus,
    sonarStatus,
    sonarDetail,
    incidentId,
    prNumber: ctx.prNumber,
    prUrl: ctx.prUrl,
    prBranch: ctx.prBranch,
    buildUrl: ctx.buildUrl,
    job: ctx.job,
    buildNumber: ctx.buildNumber,
    commentBody: lines.join('\n'),
    config,
  }
}];

